+package com.example.contact;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.List;
+
+import com.vaadin.flow.component.AbstractField;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.HasValueChangeMode;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouteAlias;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@RouteAlias("")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final EmailValidator EMAIL_VALIDATOR = new EmailValidator("");
+    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
+
+    private final MessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final List<AbstractField<?, String>> fields = List.of(name, email, phone, message);
+
+    private boolean clearing;
+    private Dialog leaveDialog;
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        for (AbstractField<?, String> field : fields) {
+            // Validation is done by this view on Send, not by the components themselves
+            ((HasValidation) field).setManualValidation(true);
+            ((HasValueChangeMode) field).setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(e -> {
+                if (!clearing) {
+                    send.setEnabled(true);
+                }
+            });
+        }
+        message.setHelperText("At most " + MAX_MESSAGE_LENGTH + " characters");
+
+        send.addThemeVariants(ButtonVariant.PRIMARY);
+        send.addClickListener(e -> send());
+        send.addClickShortcut(Key.ENTER);
+
+        FormLayout form = new FormLayout(name, email, phone, message, send);
+        form.setColspan(message, 2);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.addColumn(m -> m.sentAt().format(TIME_FORMAT)).setHeader("Sent").setAutoWidth(true);
+        refreshGrid();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, grid);
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+        messageService.send(new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue().trim(), LocalDateTime.now()));
+        refreshGrid();
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!emailValue.isEmpty()) {
+            if (!isValidEmail(emailValue)) {
+                emailError = "Enter a valid e-mail address";
+            }
+        } else if (phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (messageValue.isEmpty()) {
+            messageError = "Message is required";
+        } else if (message.getValue().length() > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        setError(name, nameError);
+        setError(email, emailError);
+        setError(phone, null);
+        setError(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static boolean isValidEmail(String value) {
+        return !EMAIL_VALIDATOR.apply(value, null).isError();
+    }
+
+    private static void setError(AbstractField<?, String> field, String error) {
+        var validatable = (HasValidation) field;
+        validatable.setErrorMessage(error);
+        validatable.setInvalid(error != null);
+    }
+
+    private void clearForm() {
+        clearing = true;
+        try {
+            fields.forEach(f -> {
+                f.clear();
+                setError(f, null);
+            });
+        } finally {
+            clearing = false;
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+
+    private boolean hasInput() {
+        return fields.stream().anyMatch(f -> !f.isEmpty());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        if (leaveDialog != null) {
+            leaveDialog.close();
+        }
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add("The form has unsent input. If you leave now, it will be lost.");
+        dialog.setCloseOnOutsideClick(false);
+        dialog.setCloseOnEsc(false);
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.ERROR);
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened() && leaveDialog == dialog) {
+                leaveDialog = null;
+            }
+        });
+        leaveDialog = dialog;
+        dialog.open();
+    }
+}
