+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest {
+
+    static Playwright playwright;
+    static Browser browser;
+
+    @LocalServerPort
+    int port;
+
+    @BeforeAll
+    static void start() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stop() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendAndLeave() {
+        Page page = browser.newPage();
+        page.setDefaultTimeout(60000);
+        page.navigate("http://localhost:" + port + "/contact");
+        assertThat(page.locator("h1")).hasText("Contact");
+        var send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
+        send.click();
+        assertThat(page.getByText("Name is required")).isVisible();
+
+        page.getByLabel("Name").fill("Bob");
+        page.getByLabel("Email").fill("bob@example.com");
+        page.getByLabel("Message").fill("Hi from the browser");
+        page.getByLabel("Name").press("Enter");
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.locator("vaadin-grid")).containsText("Hi from the browser");
+        assertThat(send).isDisabled();
+        page.getByLabel("Phone").fill("1");
+        assertThat(send).isEnabled();
+
+        page.getByText("About").click();
+        assertThat(page.getByText("Keep editing")).isVisible();
+        page.getByText("Keep editing").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
