+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import java.util.List;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField field(String label) {
+        return $(TextField.class).withCaption(label).single();
+    }
+
+    private Button button(String text) {
+        return $(Button.class).withText(text).single();
+    }
+
+    @Test
+    void emptySendShowsAllErrors() {
+        navigate(ContactView.class);
+        Button send = button("Send");
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertEquals("Name is required", field("Name").getErrorMessage());
+        assertTrue(field("Name").isInvalid());
+        EmailField email = $(EmailField.class).single();
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertEquals("Message is required", $(TextArea.class).single().getErrorMessage());
+        assertTrue($(Notification.class).all().isEmpty());
+
+        test(email).setValue("not-an-email");
+        test($(TextArea.class).single()).setValue("x".repeat(501));
+        test(send).click();
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("Message must be at most 500 characters", $(TextArea.class).single().getErrorMessage());
+        assertEquals("not-an-email", email.getValue());
+    }
+
+    @SuppressWarnings("unchecked")
+    @Test
+    void sendWithEnterThenNavigateWithoutPrompt() {
+        navigate(ContactView.class);
+        test(field("Name")).setValue("Ann");
+        test(field("Phone")).setValue("12345");
+        test($(TextArea.class).single()).setValue("Hello there");
+        fireShortcut(Key.ENTER);
+        assertFalse($(Notification.class).all().isEmpty());
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals("Hello there", test(grid).getRow(0).message());
+        assertEquals("", field("Name").getValue());
+        Button send = button("Send");
+        assertFalse(send.isEnabled());
+        test(field("Name")).setValue("B");
+        assertTrue(send.isEnabled());
+        test(field("Name")).clear();
+
+        test($(RouterLink.class).single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        grid = $(Grid.class).single();
+        assertEquals("Ann", test(grid).getRow(0).name());
+    }
+
+    @Test
+    void leavingWithInputAsks() {
+        navigate(ContactView.class);
+        test(field("Name")).setValue("Ann");
+        test($(RouterLink.class).single()).click();
+        assertEquals(1, $(Dialog.class).all().size());
+        test(button("Keep editing")).click();
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("Ann", field("Name").getValue());
+
+        test($(RouterLink.class).single()).click();
+        test(button("Discard")).click();
+        assertEquals(List.of("About"), $(H1.class).all().stream().map(H1::getText).toList());
+    }
+}
